SELECT t.title, COUNT(c.movie_id) AS num_cast_members FROM title AS t JOIN cast_info AS c ON t.id = c.movie_id WHERE t.production_year BETWEEN 2000 AND 2020 GROUP BY t.title HAVING COUNT(c.movie_id) > 10 ORDER BY num_cast_members DESC;
SELECT k.keyword, COUNT(mk.movie_id) AS num_movies FROM keyword AS k JOIN movie_keyword AS mk ON k.id = mk.keyword_id GROUP BY k.keyword HAVING COUNT(mk.movie_id) > 100 ORDER BY num_movies DESC;
SELECT n.name, COUNT(ci.person_id) AS num_roles FROM name AS n JOIN cast_info AS ci ON n.id = ci.person_id WHERE ci.role_id IN (1, 2) GROUP BY n.name HAVING COUNT(ci.person_id) > 50 ORDER BY num_roles DESC;
SELECT cn.name, cn.country_code, COUNT(mc.movie_id) AS num_movies FROM company_name AS cn JOIN movie_companies AS mc ON cn.id = mc.company_id WHERE cn.country_code IN ('[se]', '[sg]', '[cn]') AND cn.name_pcode_nf IN ('J2541', 'L5236', 'F3612') GROUP BY cn.name, cn.country_code ORDER BY num_movies DESC, cn.name ASC;
SELECT n.name, COUNT(ci.movie_id) AS num_movies, COUNT(DISTINCT ci.person_id) AS num_actors FROM name AS n JOIN cast_info AS ci ON n.id = ci.person_id JOIN movie_info AS mi ON ci.movie_id = mi.movie_id WHERE mi.info_type_id = 101 AND mi.info = 'soundtrack' GROUP BY n.name HAVING COUNT(DISTINCT ci.person_id) > 1 ORDER BY num_movies DESC, n.name ASC;
SELECT COUNT(*) FROM movie_info WHERE info_type_id = (SELECT id FROM info_type WHERE info = 'rating') AND CAST(info AS FLOAT) > 7.5;
SELECT title.title, AVG(CAST(movie_info.info AS FLOAT)) as average_rating FROM title JOIN movie_info ON title.id = movie_info.movie_id WHERE movie_info.info_type_id = (SELECT id FROM info_type WHERE info = 'rating') GROUP BY title.title HAVING AVG(CAST(movie_info.info AS FLOAT)) > 7.5;
SELECT title.title, COUNT(movie_keyword.keyword_id) as keyword_count FROM title JOIN movie_keyword ON title.id = movie_keyword.movie_id GROUP BY title.title ORDER BY keyword_count DESC;
SELECT t.title, COUNT(c.id) AS cast_count FROM title t JOIN cast_info c ON t.id = c.movie_id WHERE t.kind_id = 3 GROUP BY t.title HAVING COUNT(c.id) > 10 ORDER BY cast_count DESC;
SELECT k.keyword, COUNT(mk.movie_id) AS movie_count FROM keyword k JOIN movie_keyword mk ON k.id = mk.keyword_id GROUP BY k.keyword HAVING COUNT(mk.movie_id) > 100 ORDER BY movie_count DESC;
SELECT n.name, COUNT(ci.id) AS role_count FROM name n JOIN cast_info ci ON n.id = ci.person_id WHERE ci.role_id = 1 GROUP BY n.name HAVING COUNT(ci.id) > 5 ORDER BY role_count DESC;
